def fail(message: str) -> None:
    raise RuntimeError(message)


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def tree_hash(path: Path) -> str:
    hasher = hashlib.sha256()
    if not path.exists():
        return "MISSING"
    files = [path] if path.is_file() else sorted(
        p for p in path.rglob("*")
        if p.is_file() and "__pycache__" not in p.parts and ".pytest_cache" not in p.parts
    )
    for item in files:
        hasher.update(str(item.relative_to(ROOT)).replace("\\", "/").encode())
        hasher.update(b"\0")
        hasher.update(item.read_bytes())
        hasher.update(b"\0")
    return hasher.hexdigest()


def run(cmd: list[str], cwd: Path, label: str) -> None:
    print()
    print(f"=== {label} ===")
    print(" ".join(cmd))
    result = subprocess.run(cmd, cwd=cwd)
    if result.returncode != 0:
        fail(f"{label} failed with exit code {result.returncode}")


def patch_app(source: str) -> str:
    if "HoldingsWorkspace" in source or '"holdings"' in source:
        fail("App.tsx already appears to contain HOLD.1-G changes.")

    import_anchor = 'import TrackingWorkspace from "./components/TrackingWorkspace";'
    if source.count(import_anchor) != 1:
        fail("App.tsx import anchor changed.")
    source = source.replace(
        import_anchor,
        import_anchor + '\nimport HoldingsWorkspace from "./components/HoldingsWorkspace";',
        1,
    )

    type_anchor = 'type AppPage = "analysis" | "backtest" | "scanner" | "simulation";'
    if source.count(type_anchor) != 1:
        fail("AppPage type anchor changed.")
    source = source.replace(
        type_anchor,
        'type AppPage = "analysis" | "backtest" | "scanner" | "simulation" | "holdings";',
        1,
    )

    path_anchor = (
        'function pageFromPathname(pathname: string): AppPage {\n'
        '  const lower = pathname.toLowerCase();\n'
        '  if (lower.startsWith("/simulation")) return "simulation";\n'
        '  if (lower.startsWith("/scanner")) return "scanner";\n'
        '  if (lower.startsWith("/backtest")) return "backtest";\n'
        '  return "analysis";\n'
        '}'
    )
    path_replacement = (
        'function pageFromPathname(pathname: string): AppPage {\n'
        '  const lower = pathname.toLowerCase();\n'
        '  if (lower.startsWith("/holdings")) return "holdings";\n'
        '  if (lower.startsWith("/simulation")) return "simulation";\n'
        '  if (lower.startsWith("/scanner")) return "scanner";\n'
        '  if (lower.startsWith("/backtest")) return "backtest";\n'
        '  return "analysis";\n'
        '}'
    )
    if source.count(path_anchor) != 1:
        fail("pageFromPathname structure changed.")
    source = source.replace(path_anchor, path_replacement, 1)

    nav_anchor = (
        '          <button className={`nav-item ${appPage === "simulation" ? "active" : ""}`} '
        'onClick={() => navigateApp("simulation")}>종목 성과 추적</button>'
    )
    nav_replacement = nav_anchor + (
        '\n          <button className={`nav-item ${appPage === "holdings" ? "active" : ""}`} '
        'onClick={() => navigateApp("holdings")}>내 종목 분석</button>'
    )
    if source.count(nav_anchor) != 1:
        fail("Top navigation structure changed.")
    source = source.replace(nav_anchor, nav_replacement, 1)

    render_anchor = (
        '          ) : appPage === "scanner" ? (\n'
        '            <ScannerPanel\n'
        '              onAnalyzeStock={(item) => {\n'
        '                chooseStock(item);\n'
        '                navigateApp("backtest");\n'
        '              }}\n'
        '            />\n'
        '          ) : (\n'
        '            <TrackingWorkspace />\n'
        '          )}'
    )
    render_replacement = (
        '          ) : appPage === "scanner" ? (\n'
        '            <ScannerPanel\n'
        '              onAnalyzeStock={(item) => {\n'
        '                chooseStock(item);\n'
        '                navigateApp("backtest");\n'
        '              }}\n'
        '            />\n'
        '          ) : appPage === "simulation" ? (\n'
        '            <TrackingWorkspace />\n'
        '          ) : (\n'
        '            <HoldingsWorkspace />\n'
        '          )}'
    )
    if source.count(render_anchor) != 1:
        fail("App page render branch changed.")
    source = source.replace(render_anchor, render_replacement, 1)
    return source


def main() -> int:
    print("PROJECT ROOT:", ROOT)
    print("HOLD.1-G — 내 종목 분석 UI")
    print("Theme support: LIGHT + DARK")
    print("Backend changes: NO")
    print("Realtime KIS overlay: NO")
    print("Actual order UI/API: NO")

    for path in (APP, STYLES):
        if not path.is_file():
            fail(f"Required frontend file missing: {path}")
    for path in (SERVICE, COMPONENT, HOLDINGS_CSS):
        if path.exists():
            fail(f"Target already exists: {path}")

    style_text = STYLES.read_text(encoding="utf-8-sig")
    required_theme_markers = (
        ':root {',
        'html[data-theme="dark"]',
        'html[data-theme="light"]',
        '--bg-page:',
        '--bg-surface:',
        '--bg-input:',
        '--text-primary:',
        '--border-default:',
        '--accent-primary:',
    )
    missing_theme = [marker for marker in required_theme_markers if marker not in style_text]
    if missing_theme:
        print()
        print("G.0 SOURCE AUDIT: STOP")
        print("Light/Dark theme structure differs from expected. No files changed.")
        print("Missing theme markers:", missing_theme)
        return 2

    app_before = APP.read_text(encoding="utf-8-sig")
    app_after = patch_app(app_before)

    if 'html[data-theme=' in CSS_CONTENT or ':root' in CSS_CONTENT:
        fail("holdings.css must consume the existing theme; it must not define a new theme.")
    if "#fff" in CSS_CONTENT.lower() or "#ffffff" in CSS_CONTENT.lower():
        fail("holdings.css contains a forbidden white surface literal.")

    protected_backend = tree_hash(ROOT / "backend")
    styles_before = sha256(STYLES)

    created: list[Path] = []
    app_changed = False

    try:
        SERVICE.write_text(SERVICE_CONTENT, encoding="utf-8", newline="\n")
        created.append(SERVICE)
        COMPONENT.write_text(COMPONENT_CONTENT, encoding="utf-8", newline="\n")
        created.append(COMPONENT)
        HOLDINGS_CSS.write_text(CSS_CONTENT, encoding="utf-8", newline="\n")
        created.append(HOLDINGS_CSS)
        APP.write_text(app_after, encoding="utf-8", newline="\n")
        app_changed = True

        print()
        print("=== HOLD.1-G STATIC CONTRACT ===")
        app_now = APP.read_text(encoding="utf-8")
        component_now = COMPONENT.read_text(encoding="utf-8")
        service_now = SERVICE.read_text(encoding="utf-8")
        css_now = HOLDINGS_CSS.read_text(encoding="utf-8")

        checks = {
            "AppPage holdings": '"holdings"' in app_now,
            "/holdings route": 'startsWith("/holdings")' in app_now,
            "top nav": ">내 종목 분석</button>" in app_now,
            "workspace render": "<HoldingsWorkspace />" in app_now,
            "watch API": "/api/holdings/watch" in service_now,
            "analysis refresh API": "/analysis/refresh" in service_now,
            "timeline API": "/timeline" in service_now,
            "KIS sync API": "/api/holdings/kis/sync" in service_now,
            "no order API": "order_cash" not in service_now and "place_order" not in service_now,
            "no realtime quote": "/quote" not in service_now,
            "light/dark tokens": "var(--bg-surface)" in css_now and "var(--text-primary)" in css_now,
            "no theme fork": 'html[data-theme=' not in css_now and ':root' not in css_now,
            "EOD wording": "최신 확정 일봉 기준" in component_now,
            "KIS no trade inference": "매수 감지" not in component_now and "매도 감지" not in component_now,
        }
        failed = [name for name, ok in checks.items() if not ok]
        for name, ok in checks.items():
            print(f"{name}: {'PASS' if ok else 'FAIL'}")
        if failed:
            fail("Static contract failed: " + ", ".join(failed))

        npm = shutil.which("npm.cmd") or shutil.which("npm")
        if not npm:
            fail("npm was not found.")
        run([npm, "run", "build"], FRONTEND, "Frontend build")

        if tree_hash(ROOT / "backend") != protected_backend:
            fail("Backend files changed during HOLD.1-G.")
        if sha256(STYLES) != styles_before:
            fail("Global styles.css changed during HOLD.1-G; this step must consume existing theme tokens only.")

        print()
        print("HOLD.1-G IMPLEMENTATION READY")
        print("Added:")
        print(" - frontend/src/components/HoldingsWorkspace.tsx")
        print(" - frontend/src/services/holdingsApi.ts")
        print(" - frontend/src/holdings.css")
        print("Modified:")
        print(" - frontend/src/App.tsx (page route/nav/render only)")
        print("Light mode support: PASS (existing tokens reused)")
        print("Dark mode support: PASS (existing tokens reused)")
        print("Holdings API service: PASS")
        print("Watch add/remove UI: PASS")
        print("Manual holding record UI: PASS")
        print("Analysis refresh UI: PASS")
        print("KIS balance sync UI: PASS")
        print("Combined timeline UI: PASS")
        print("Realtime price overlay added: NO")
        print("External integration panel added here: NO")
        print("Broker order UI/API added: NO")
        print("Backend changed: NO")
        print("Frontend build: PASS")
        print()
        print("NEXT: run the app and do one visual UAT in Dark + Light.")
        return 0

    except Exception:
        if app_changed:
            APP.write_text(app_before, encoding="utf-8", newline="\n")
        for path in reversed(created):
            if path.exists():
                path.unlink()
        print()
        print("FAILED — HOLD.1-G changes were rolled back.")
        raise


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print()
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(1)
